template.script:
async function configurarYObtenerDatos() {
    const modelo = document.getElementById('modelo').value;
    const fecha_inicio = document.getElementById('fecha_inicio').value;
    const fecha_fin = document.getElementById('fecha_fin').value;
    const campos = document.getElementById('campos').value.split(',');

    const configResponse = await fetch('/configurar_grafico', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({modelo, fecha_inicio, fecha_fin, campos})
    });
    const configData = await configResponse.json();

    const dataResponse = await fetch('/obtener_datos_grafico', {method: 'POST'});
    const data = await dataResponse.json();
    if (data.error) {
        console.error(data.error);
    } else {
        const ctx = document.getElementById('myChart').getContext('2d');
        new Chart(ctx, {
            type: 'bar',
            data: {
                labels: data.labels,
                datasets: data.datasets
            },
            options: {}
        });
    }
}
